export type Locale = keyof typeof catalogs;
export type MessageKey = keyof (typeof catalogs)["ko"];

type LocaleContextValue = { locale: Locale; setLocale: (locale: Locale) => void; t: (key: MessageKey) => string };
const LocaleContext = createContext<LocaleContextValue | null>(null);
const storageKey = "gss.mobile.locale.v1";

export function LocaleProvider({ children }: PropsWithChildren) {
  const [locale, setLocaleState] = useState<Locale>("ko");
  useEffect(() => { void AsyncStorage.getItem(storageKey).then((stored) => { if (stored === "ko" || stored === "en") setLocaleState(stored); }); }, []);
  const value = useMemo<LocaleContextValue>(() => ({ locale, setLocale(next) { setLocaleState(next); void AsyncStorage.setItem(storageKey, next); }, t: (key) => catalogs[locale][key] }), [locale]);
  return <LocaleContext.Provider value={value}>{children}</LocaleContext.Provider>;
}

export function useI18n(): LocaleContextValue {
  const context = useContext(LocaleContext);
  if (!context) throw new Error("useI18n must be used inside LocaleProvider");
  return context;
}
